import os, re, subprocess, collections

ROOT="/bench/repo"

# 1. Enumerate declarations under internal/ (non-test files)
decl_re = re.compile(r'^func\s+(?:\((?P<recv>[^)]*)\)\s+)?(?P<name>[A-Za-z_][A-Za-z0-9_]*)\s*(?:\[[^\]]*\])?\(')

decls = []  # (name, recvtype, file, package)
internal_files = []
for dirpath, dirs, files in os.walk(os.path.join(ROOT,"internal")):
    for f in files:
        if f.endswith(".go") and not f.endswith("_test.go"):
            internal_files.append(os.path.join(dirpath,f))

pkg_re = re.compile(r'^package\s+(\w+)')
for path in internal_files:
    pkg=None
    with open(path) as fh:
        for line in fh:
            if pkg is None:
                m=pkg_re.match(line)
                if m: pkg=m.group(1)
            m=decl_re.match(line)
            if m:
                name=m.group('name')
                recv=m.group('recv') or ''
                recvtype=''
                if recv:
                    parts=recv.split()
                    recvtype=parts[-1].lstrip('*')
                decls.append((name,recvtype,path,pkg))

print("Total decls under internal (non-test):",len(decls))

# Collect all .go files repo-wide (exclude vendor)
all_go=[]
for dirpath, dirs, files in os.walk(ROOT):
    if '/vendor/' in dirpath or dirpath.endswith('/vendor'): continue
    if '/.git' in dirpath: continue
    for f in files:
        if f.endswith(".go"):
            all_go.append(os.path.join(dirpath,f))

# Read all files into memory, strip line comments crudely
filetext={}
for p in all_go:
    with open(p, errors='replace') as fh:
        filetext[p]=fh.readlines()

# Count call sites for each unique name across repo.
# We count occurrences of `Name(` that are NOT the declaration and not in a comment line.
name_call_counts={}
def count_name(name):
    pat=re.compile(r'(?<![A-Za-z0-9_.])'+re.escape(name)+r'\s*\(')
    total=0
    for p,lines in filetext.items():
        for ln in lines:
            s=ln.lstrip()
            if s.startswith('//') or s.startswith('*'): continue
            if s.startswith('func '):  # skip declaration lines
                # only skip if it's declaring this name
                pass
            for m in pat.finditer(ln):
                # ensure not preceded by 'func ' as declaration
                total+=1
    return total

names=set(n for n,_,_,_ in decls)
print("Unique names:",len(names))
