use strict; use warnings;
use File::Find;
my $ROOT="/bench/repo";
my @intfiles;
find(sub{
  return unless /\.go$/;
  return if /_test\.go$/;
  push @intfiles, $File::Find::name;
}, "$ROOT/internal");

