use strict; use warnings;
use File::Find;
my $ROOT="/bench/repo";
my @gofiles;
find(sub{
  return unless /\.go$/;
  my $p=$File::Find::name;
  return if $p=~m{/vendor/};
  push @gofiles, $p;
}, $ROOT);

# tally every identifier immediately followed by '(' across repo,
# excluding comment lines and func-declaration lines.
my %count;      # name -> total call-ish occurrences
my %countfiles; # name -> distinct files with a call
for my $f (@gofiles){
  open my $fh,'<',$f or next;
  my %seenfile;
  while(my $l=<$fh>){
    my $s=$l; $s=~s/^\s+//;
    next if $s=~m{^//};
    next if $s=~m{^\*};
    next if $s=~/^func\b/;   # skip declaration lines
    while($l=~/([A-Za-z_][A-Za-z0-9_]*)\s*\(/g){
      my $n=$1;
      # skip go keywords that take parens
      next if $n=~/^(if|for|switch|return|go|defer|select|func|struct|interface|map|chan)$/;
      $count{$n}++;
      $seenfile{$n}=1;
    }
  }
  close $fh;
  $countfiles{$_}++ for keys %seenfile;
}

# load declared names (unique)
open my $d,'<','/tmp/decls.tsv' or die;
my %declnames;
while(<$d>){ chomp; my @f=split/\t/; $declnames{$f[0]}=1; }
close $d;

# print name  callcount  filecount  for declared names, sorted desc
for my $n (sort {($count{$b}//0)<=>($count{$a}//0)} keys %declnames){
  printf "%d\t%d\t%s\n", ($count{$n}//0), ($countfiles{$n}//0), $n;
}
