cat > /tmp/attr.pl << 'PLEOF'
use strict; use warnings;
use File::Find;
my $ROOT="/bench/repo";

# load repo go files (non-vendor), keep dir
my @gofiles;
find(sub{ return unless /\.go$/; my $p=$File::Find::name; return if $p=~m{/vendor/}; push @gofiles,$p; }, $ROOT);
my %lines; # file -> arrayref of lines
for my $f (@gofiles){ open my $fh,'<',$f or next; my @L=<$fh>; close $fh; $lines{$f}=\@L; }

sub dirof { my $p=shift; $p=~s{/[^/]+$}{}; return $p; }

# count qualified pkg.Name( occurrences repo-wide
sub count_qual {
  my ($pkg,$name)=@_;
  my $re=qr/\b\Q$pkg\E\.\Q$name\E\s*\(/;
  my $t=0;
  for my $f (@gofiles){
    for my $l (@{$lines{$f}}){
      my $s=$l; $s=~s/^\s+//; next if $s=~m{^//}||$s=~m{^\*};
      my @m=($l=~/$re/g); $t+=scalar(@m);
    }
  }
  return $t;
}
# count bare Name( within a given dir (intra-package), excluding func decl lines
sub count_bare_indir {
  my ($dir,$name)=@_;
  my $re=qr/(?<![A-Za-z0-9_.])\Q$name\E\s*\(/;
  my $t=0;
  for my $f (@gofiles){
    next unless dirof($f) eq $dir;
    for my $l (@{$lines{$f}}){
      my $s=$l; $s=~s/^\s+//; next if $s=~m{^//}||$s=~m{^\*}; next if $s=~/^func\b/;
      my @m=($l=~/$re/g); $t+=scalar(@m);
    }
  }
  return $t;
}
# count method calls .Name( repo-wide (preceded by ident or ')'), excl decl lines
sub count_method {
  my ($name)=@_;
  my $re=qr/(?<=[A-Za-z0-9_)\]])\.\Q$name\E\s*\(/;
  my $t=0; my $files=0;
  for my $f (@gofiles){ my $hit=0;
    for my $l (@{$lines{$f}}){
      my $s=$l; $s=~s/^\s+//; next if $s=~m{^//}||$s=~m{^\*}; next if $s=~/^func\b/;
      my @m=($l=~/$re/g); if(@m){$t+=scalar(@m);$hit=1;}
    }
    $files++ if $hit;
  }
  return ($t,$files);
}

# load decls
open my $d,'<','/tmp/decls.tsv' or die; my @decls;
while(<$d>){ chomp; my($name,$recv,$pkg,$file)=split/\t/; push @decls,[$name,$recv//'',$pkg,$file]; }
close $d;

# how many types declare each method name (collision detector)
my %methtypes;
for my $r (@decls){ $methtypes{$r->[0]}{$r->[1]}=1 if $r->[1] ne ''; }

my @out;
for my $r (@decls){
  my ($name,$recv,$pkg,$file)=@$r;
  my $dir=dirof($file);
  if($recv eq ''){
    my $q=count_qual($pkg,$name);
    my $b=count_bare_indir($dir,$name);
    my $attr=$q+$b;
    push @out, sprintf("%d\tFUNC\t%d(qual)+%d(intra)\t%s.%s\t%s", $attr,$q,$b,$pkg,$name,$file);
  } else {
    my ($m,$fl)=count_method($name);
    my $ncoll=scalar(keys %{$methtypes{$name}});
    push @out, sprintf("%d\tMETH\t.%s( x%d files, %d types-with-name\t(%s).%s\t%s", $m,$name,$fl,$ncoll,$recv,$name,$file);
  }
}
# dedupe identical function symbols (same pkg.name declared once) - decls unique already
for my $line (sort { (split/\t/,$b)[0] <=> (split/\t/,$a)[0] } @out){
  print $line,"\n";
}
